const stalePaymentAccountCreateStoreIDs = `-- name: StalePaymentAccountCreateStoreIDs :many
SELECT store_id
FROM payment.accounts
WHERE create_completed_at IS NULL AND create_failed_at IS NULL AND purge_pending_at IS NULL
  AND updated_at < $1 AND store_id > $2
ORDER BY store_id
LIMIT $3
`

type StalePaymentAccountCreateStoreIDsParams struct {
	IdleBefore   time.Time
	AfterStoreID int64
	Batch        int32
}

func (q *Queries) StalePaymentAccountCreateStoreIDs(ctx context.Context, arg StalePaymentAccountCreateStoreIDsParams) ([]int64, error) {
	rows, err := q.db.Query(ctx, stalePaymentAccountCreateStoreIDs, arg.IdleBefore, arg.AfterStoreID, arg.Batch)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int64{}
	for rows.Next() {
		var store_id int64
		if err := rows.Scan(&store_id); err != nil {
			return nil, err
		}
		items = append(items, store_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const unresolvedPaymentAccountStoreIDs = `-- name: UnresolvedPaymentAccountStoreIDs :many
SELECT store_id
FROM payment.accounts
WHERE external_account_id IS NULL AND create_called_at IS NOT NULL AND create_completed_at IS NULL AND purge_pending_at IS NULL AND create_refused_at IS NULL
  AND create_called_at <= $1::timestamptz
  AND NOT (create_failed_at IS NOT NULL AND create_called_at <= $2::timestamptz)
  AND store_id > $3
ORDER BY store_id
LIMIT $4
`

